from datetime import datetime, timezone
from typing import Literal, Optional
from uuid import uuid4
from pydantic import BaseModel, Field


def utcnow() -> datetime:
    return datetime.now(timezone.utc)


class RiskAssessment(BaseModel):
    """Deterministic risk evaluation generated by the Risk Engine (Phase 6).

    Contains a 0-100 severity score, risk level bucket, and transparent factor breakdown dict.
    """

    id: str = Field(default_factory=lambda: str(uuid4()))
    event_id: str = Field(..., description="ID of associated DisruptionEvent")
    entity_id: str = Field(..., description="ID of affected BusinessEntity")
    severity_score: float = Field(
        ..., ge=0.0, le=100.0, description="Computed deterministic score (0.0 to 100.0)"
    )
    factors: dict[str, float] = Field(
        ..., description="Transparent breakdown of weighted factor contributions"
    )
    risk_level: Literal["low", "medium", "high", "critical"] = Field(
        ..., description="Risk severity bucket"
    )
    computed_at: datetime = Field(default_factory=utcnow)


class Alert(BaseModel):
    """Actionable, severity-tagged alert presented on the operational dashboard."""

    id: str = Field(default_factory=lambda: str(uuid4()))
    event_id: str = Field(..., description="ID of associated DisruptionEvent")
    risk_assessment_id: str = Field(..., description="ID of associated RiskAssessment")
    entity_ids: list[str] = Field(..., min_length=1, description="Affected direct and downstream entity IDs")
    message: str = Field(..., description="Templated, human-readable alert summary message")
    dedupe_key: str = Field(..., description="Hash of (source_url + entity_id) to prevent duplicate alerts")
    created_at: datetime = Field(default_factory=utcnow)
    acknowledged: bool = Field(default=False, description="Whether alert has been acknowledged by user")
    acknowledged_at: Optional[datetime] = Field(default=None, description="Timestamp of acknowledgment")
